        !byte $00,$07,$0e               ; offset of SID voice 1-3 registers from $D400
music_waveforms
        !byte $11,$21,$41,$81           ; control values of $A0-$A3: triangle, sawtooth, pulse, noise (gate on)
; Command $Bn: copies the 6 envelope bytes of instrument n (music_instruments + n * 8) into the
; voice's part of music_envelopes. They take effect with the next articulation command $A4-$A6.
music_cmd_instrument
        tya
        and #$07
        asl
        asl
        asl
        tay
        ldx #$00
        lda music_voice
        beq music_cmd_instrument_voice0
        lsr
        bcs music_cmd_instrument_voice1
music_cmd_instrument_voice2
        lda music_instruments,y
        sta music_envelopes+$c,x
        iny
        inx
        cpx #$06
        bne music_cmd_instrument_voice2
        jmp music_cmd_next
music_cmd_instrument_voice0
        lda music_instruments,y
        sta music_envelopes,x
        iny
        inx
        cpx #$06
        bne music_cmd_instrument_voice0
        jmp music_cmd_next
music_cmd_instrument_voice1
        lda music_instruments,y
        sta music_envelopes+6,x
        iny
        inx
        cpx #$06
        bne music_cmd_instrument_voice1
        jmp music_cmd_next
; Command $Cx: the next two stream bytes (low, high) go to the pulse width registers of the voice.
music_cmd_pulse_width
        jsr music_read_byte
        ldx music_voice
        ldy sid_voice_offsets,x
        sta PWLO1,y
        jsr music_read_byte
        ldx music_voice
        ldy sid_voice_offsets,x
        sta PWHI1,y
        jmp music_cmd_next
; Command $Dn: filter preset n (music_filter_presets): cutoff to $D415/$D416, mode to
; music_filter_mode; the next stream byte (voice routing bits) OR the preset resonance byte gives
; music_resonance. The voice's next note writes $D417/$D418. The title tune does not use it.
music_cmd_filter
; not executed $e779-$e7b1
        tya
        and #$07
        asl
        asl
        clc
        adc #$40                        ; music_instruments + $40 = music_filter_presets
        tay
        lda music_instruments,y
        sta CUTLO
        iny
        lda music_instruments,y
        sta CUTHI
        iny
        lda music_instruments,y
        pha
        iny
        lda music_instruments,y
        sta music_filter_mode
        ldx music_voice
        inx
        stx music_volume_voice
        jsr music_read_byte
        sta music_temp
        pla
        ora music_temp
        sta music_resonance
        jmp music_cmd_next
; Command $Ex: the next stream byte is the tempo in frames per tick (music_tempo).
music_cmd_tempo
        jsr music_read_byte
        sta music_tempo
        sta music_tempo_counter
        jmp music_cmd_next
